const cp=require('child_process');const files=cp.execFileSync('git',['ls-files','--others','--exclude-standard','-z'],{encoding:'utf8'}).split('\0').filter(p=>p&&!p.startsWith('docs/review/p1-query-workspace-2026-10-11/')&&/\.(?:java|js|cjs|vue|sql|md|json|ps1|mmd)$/.test(p));const failures=[];for(const file of files){const r=cp.spawnSync('git',['-c','core.safecrlf=false','diff','--no-index','--check','--','NUL',file],{encoding:'utf8'});if(![0,1].includes(r.status)||r.stdout.trim()||r.stderr.trim())failures.push({file,exitCode:r.status,output:r.stdout+r.stderr});}console.log(JSON.stringify({checked:files.length,failures,passed:failures.length===0,note:'git diff --no-index returns 1 for nonempty files differing from NUL; only empty diagnostics with exit 0/1 are accepted'}));if(failures.length)process.exit(1);
